16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.util.Luhn;
20	import org.springframework.samples.petclinic.util.RegistrationDatePolicy;
21	
22	import jakarta.persistence.*;
23	import jakarta.validation.constraints.NotEmpty;
24	import jakarta.validation.constraints.Pattern;
25	
26	import java.time.LocalDate;
27	import java.time.temporal.ChronoUnit;
28	import java.util.*;
29	
30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "city")
46	    @NotEmpty
47	    private String city;
48	
49	    @Column(name = "postcode")
50	    private String postcode;
51	
52	    @Column(name = "telephone")
53	    @NotEmpty
54	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
55	    private String telephone;
56	
57	    @Column(name = "email")
58	    private String email;
59	
60	    @Column(name = "birth_date")
61	    private LocalDate birthDate;
62	
63	    @Column(name = "registration_date")
64	    private LocalDate registrationDate;
65	
66	    @Column(name = "customer_code")
67	    private String customerCode;
68	
69	    @Column(name = "household_id")
70	    private String householdId;
71	
72	    @Column(name = "namesake_count")
73	    private Integer namesakeCount;
74	
75	    @Column(name = "household_size")
76	    private Integer householdSize;
77	
78	    @Column(name = "possible_duplicate")
79	    private Boolean possibleDuplicate;
80	
81	    @Column(name = "possible_duplicate_of")
82	    private Integer possibleDuplicateOf;
83	
84	    /**
85	     * Whether this owner was knowingly created into a shared household (the request declared shared
86	     * membership). A declared member is not treated as a suspected duplicate. Set per request and
87	     * never persisted.
88	     */
89	    @Transient
90	    private boolean declaredHouseholdMember;
91	
92	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
93	    private Set<Pet> pets;
94	
95	    /**
96	     * Resolve the registration date at creation time: default it to the server's
97	     * current date when none was supplied, and roll a weekend date forward to the
98	     * next business day so every value derived from it (such as the membership
99	     * number's year segment) uses the adjusted date.
100	     */
101	    @PrePersist
102	    private void resolveRegistrationDate() {
103	        this.registrationDate = RegistrationDatePolicy.effectiveDate(this.registrationDate);
104	    }
105	
106	    public String getAddress() {
107	        return this.address;
108	    }
109	
110	    public void setAddress(String address) {
111	        this.address = address;
112	    }
113	
114	    public String getCity() {
115	        return this.city;
116	    }
117	
118	    public void setCity(String city) {
119	        this.city = city;
120	    }
121	
122	    public String getPostcode() {
123	        return this.postcode;
124	    }
125	
126	    public void setPostcode(String postcode) {
127	        this.postcode = postcode;
128	    }
129	
130	    /**
131	     * The owner's locality: the region component of its {@link #customerCode}
132	     * identity (see {@link CustomerCode}), or {@code null} when no customer code
133	     * is assigned. The region was derived from the owner's postcode and city when
134	     * the identity was minted, so the locality now follows the identity rather than
135	     * being recomputed from the current city and postcode.
136	     */
137	    public String getLocality() {
138	        return CustomerCode.regionOf(this.customerCode);
139	    }
140	
141	    public String getTelephone() {
142	        return this.telephone;
143	    }
144	
145	    public void setTelephone(String telephone) {
146	        this.telephone = telephone;
147	    }
148	
149	    public String getEmail() {
150	        return this.email;
151	    }
152	
153	    public void setEmail(String email) {
154	        this.email = email;
155	    }
156	
157	    public LocalDate getBirthDate() {
158	        return this.birthDate;
159	    }
160	
161	    public void setBirthDate(LocalDate birthDate) {
162	        this.birthDate = birthDate;
163	    }
164	
165	    /**
166	     * The owner's {@link AgeBand age band} on the {@link #registrationDate}, derived
167	     * from the {@link #birthDate}, or {@code null} when no birth date is on file.
168	     */
169	    public AgeBand getAgeBand() {
170	        return AgeBand.on(this.birthDate, this.registrationDate);
171	    }
172	
173	    public LocalDate getRegistrationDate() {
174	        return this.registrationDate;
175	    }
176	
177	    public void setRegistrationDate(LocalDate registrationDate) {
178	        this.registrationDate = registrationDate;
179	    }
180	
181	    public String getCustomerCode() {
182	        return this.customerCode;
183	    }
184	
185	    public void setCustomerCode(String customerCode) {
186	        this.customerCode = customerCode;
187	    }
188	
189	    /**
190	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'}
191	     * where {@code YY} is the last two digits of the {@link #registrationDate}
192	     * year (e.g. {@code "NSW-3F2A9C1D-M26"}). Derived from the owner's own fields.
193	     */
194	    public String getMembershipNumber() {
195	        if (this.customerCode == null || this.registrationDate == null) {
196	            return null;
197	        }
198	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
199	    }
200	
201	    /**
202	     * The Luhn check digit (0-9) computed over the digits of the
203	     * {@link #customerCode}, or {@code null} when no customer code is assigned.
204	     */
205	    public Integer getCheckDigit() {
206	        if (this.customerCode == null) {
207	            return null;
208	        }
209	        return Luhn.checkDigit(this.customerCode);
210	    }
211	
212	    public String getHouseholdId() {
213	        return this.householdId;
214	    }
215	
216	    public void setHouseholdId(String householdId) {
217	        this.householdId = householdId;
218	    }
219	
220	    /**
221	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
222	     * normalized telephone, the (lower-cased) email or an empty string when absent, and the
223	     * household id or an empty string when absent, joined with {@code '|'} (e.g.
224	     * {@code "+61412345678|jo@example.com|3F2A9C1D4B6E8071"}). Two owners are the same person only
225	     * when their whole identity keys are equal; because the telephone is part of the key, household
226	     * members with different telephones have different keys.
227	     */
228	    public String getIdentityKey() {
229	        return String.join("|",
230	            this.telephone == null ? "" : this.telephone,
231	            this.email == null ? "" : this.email,
232	            this.householdId == null ? "" : this.householdId);
233	    }
234	
235	    /** Tenure, in days, beyond which an owner earns the tenure membership points. */
236	    private static final long TENURE_DAYS_FOR_POINTS = 365;
237	
238	    /** Household size at or above which an owner earns the household membership points. */
239	    private static final int HOUSEHOLD_SIZE_FOR_POINTS = 3;
240	
241	    /**
242	     * The owner's membership points, a score derived from the owner's own
243	     * fields. Starts at {@code 0}, gains {@code 2} when a contact email is on
244	     * file, gains {@code 1} when the owner has no namesakes, gains {@code 2}
245	     * when the owner belongs to a household of {@value #HOUSEHOLD_SIZE_FOR_POINTS}
246	     * or more, and gains {@code 3} when the owner's {@link #getTenureDays()
247	     * tenure} exceeds {@value #TENURE_DAYS_FOR_POINTS} days.
248	     */
249	    public Integer getMembershipPoints() {
250	        int points = 0;
251	        boolean hasEmail = this.email != null && !this.email.isEmpty();
252	        if (hasEmail) {
253	            points += 2;
254	        }
255	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
256	        if (noNamesakes) {
257	            points += 1;
258	        }
259	        boolean largeHousehold = this.householdSize != null && this.householdSize >= HOUSEHOLD_SIZE_FOR_POINTS;
260	        if (largeHousehold) {
261	            points += 2;
262	        }
263	        Long tenureDays = getTenureDays();
264	        if (tenureDays != null && tenureDays > TENURE_DAYS_FOR_POINTS) {
265	            points += 3;
266	        }
267	        return points;
268	    }
269	
270	    /**
271	     * The owner's membership level, a number from 1 to 4 mapped from the owner's
272	     * {@link #getMembershipPoints() membership points}: {@code 1} for 0-1 points,
273	     * {@code 2} for 2-3, {@code 3} for 4-5 and {@code 4} for 6 or more.
274	     */
275	    public Integer getMembershipLevel() {
276	        int points = getMembershipPoints();
277	        if (points <= 1) {
278	            return 1;
279	        }
280	        if (points <= 3) {
281	            return 2;
282	        }
283	        if (points <= 5) {
284	            return 3;
285	        }
286	        return 4;
287	    }
288	
289	    /**
290	     * The owner's tenure: the number of whole days from the {@link #registrationDate}
291	     * to the server's current date, or {@code null} when no registration date is on
292	     * file. Never negative for a registration date that is today or earlier.
293	     */
294	    public Long getTenureDays() {
295	        if (this.registrationDate == null) {
296	            return null;
297	        }
298	        return ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
299	    }
