56	 */
57	@ControllerAdvice
58	public class ExceptionControllerAdvice {
59	
60	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
61	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
62	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
63	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
64	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the same identity already exists";
65	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city has already reached its maximum number of owners";
66	    private static final String ERROR_DAILY_LIMIT_REACHED = "The maximum number of owners that may be registered today has already been reached";
67	    private static final String ERROR_FUTURE_REGISTRATION_DATE = "The registration date must not be later than the server date";
68	    private static final String ERROR_DISPOSABLE_EMAIL = "The owner's email domain is not accepted";
69	
70	    /**
71	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
72	     * class.
73	     *
74	     * @param e     Object referring to the thrown exception.
75	     * @param status HTTP response status.
76	     * @param url URL request.
77	     */
78	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
79	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
80	        problemDetail.setType(URI.create(url.toString()));
81	        problemDetail.setTitle(e.getClass().getSimpleName());
