26	public final class EmailNormalizer {
27	
28	    private EmailNormalizer() {
29	    }
30	
31	    /**
32	     * Returns the supplied email lower-cased, or {@code null} when no email was provided.
33	     *
34	     * @param email the email as submitted, possibly {@code null} or blank
35	     * @return the lower-cased email, or {@code null} when the input is {@code null} or blank
36	     */
37	    public static String normalize(String email) {
38	        if (email == null || email.isBlank()) {
39	            return null;
40	        }
41	        return email.trim().toLowerCase(Locale.ROOT);
42	    }
